let lang=localStorage.getItem('datalens-language')||'zh', view='data', rows=penguins(), original=structuredClone(rows), cols=E.columns(rows), dataset='penguins.csv', isSample=true, history=[], undo=[], detailPage=0, detailOrder='original', visible=[...cols], analysisResult=null;
const t=(zh,en)=>lang==='zh'?zh:en, esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
