function empty(s){return '<div class="empty">'+icon('chart')+s+'</div>';}
function render(){
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=t('DataLens · 数据探索工作台','DataLens · Data exploration studio');
 const title=navs().find(n=>n[0]===view)?.[2]||t('使用指南','Getting started');
 $('#app').innerHTML='<aside class="sidebar"><a href="#" class="brand" data-act="data"><span class="brand-mark">'+icon('logo')+'</span>DataLens<span style="color:#7963e9">.</span></a><div class="side-caption">'+t('工作空间','Workspace')+'</div><nav>'+navs().map(n=>btn(n[0],n[2]+(n[0]==='history'&&history.length?'<span class="badge">'+history.length+'</span>':''),n[1],'nav-btn '+(view===n[0]?'active':''))).join('')+'</nav>'+datasetPicker()+'</aside><div class="shell"><header class="topbar"><div class="breadcrumb">'+btn('menu','','menu','ghost mobile-menu','aria-label="'+t('打开菜单','Open menu')+'"')+'<span>'+t('工作空间','Workspace')+'</span><span>/</span><strong>'+title+'</strong></div><div class="top-actions">'+datasetSize()+''+btn('language',lang==='zh'?'EN / 中文':'中文 / EN','globe','lang')+btn('help','','help','ghost','aria-label="'+t('使用指南','Help')+'"')+'</div></header><main class="main">'+heading()+(view==='data'?dataView():view==='clean'?cleanView():view==='analysis'?analysisView():view==='history'?historyView():helpView())+'<footer class="footer"><span>DataLens Studio</span><span>'+t('可视化导论课程项目','Introduction to Visualization project')+' / 2026</span></footer></main></div>';
 if(view==='data')renderProfile();if(view==='clean'){renderPrepare();if(pending&&pending.kind!=='prepare')showPreview();}if(view==='analysis')renderAnalysisResult();
}
function heading(){
 const titles={
  overview:[t('数据概览','Overview'),t('查看数据规模、质量、趋势和分布。','View dataset size, quality, trends and distributions.')],
  data:[t('数据','Data'),t('从分布中认识数据，查看字段质量与分布。','Understand your data through distributions. Inspect field quality and distributions.')],
  clean:[t('处理','Prepare'),t('先预览变化，再应用清洗、计算与多表合并。','Preview changes before cleaning, calculating or joining tables.')],
  analysis:[t('分析','Analyze'),t('描述统计、分组聚合、透视表和相关性分析。','Descriptive statistics, grouping, pivot tables and correlations.')],
  history:[t('操作记录','Activity history'),t('查看数据变换记录和对应的 pandas 操作。','Review transformations and corresponding pandas operations.')],
  help:[t('使用指南','User guide'),t('功能说明、数据格式和计算口径。','Features, file formats and calculation methods.')]
 };
 const [h,p]=titles[view]||titles.help;
 return '<div class="heading spread"><div><h1>'+h+'</h1></div><div class="header-buttons">'+(view==='data'?btn('export',t('导出数据','Export data'),'download')+btn('import',t('添加数据集','Add dataset'),'plus','primary'):view==='clean'?btn('history',t('操作记录','History'),'clock')+btn('undo',t('撤销','Undo'),'undo','',undo.length?'':'disabled')+btn('reset',t('重置','Reset'),'reset','ghost'):'' )+'</div></div>';
}
function analysisView(){
 studySpec=reconcileStudy(rows,cols,studySpec,isSample);
 const spec=groupSpec||initialConfig(rows).groupSpec,numeric=colopts(true);
 return studyView.render(rows,cols,studySpec,isSample,dataset)+`<details class="card study-advanced"><summary>${t('统计明细与透视表','Statistics and pivot tables')}</summary><div class="card-pad"><div class="form-row">${field(t('行维度','Rows'),select('groupRow',colopts(),spec.r))}${field(t('列维度','Columns'),select('groupCol',[['',t('无','None')],...colopts()],spec.c))}${field(t('指标','Metric'),select('groupVal',colopts(),spec.v))}${field(t('聚合方式','Aggregation'),select('groupAgg',aggopts(),spec.fn))}${btn('aggregate',t('计算明细','Calculate'),'analysis','primary')}</div><div id="analysisResult"></div><h3 class="study-stats-title">${t('全部数值字段的描述统计','Descriptive statistics for numeric fields')}</h3><div class="table-scroll"><table><thead><tr>${[t('字段','Field'),t('有效值','Valid'),t('均值','Mean'),t('标准差','Std'),t('最小','Min'),'Q1',t('中位数','Median'),'Q3',t('最大','Max')].map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${numeric.map(([k])=>{const s=E.describe(rows.map(r=>r[k]));return '<tr><th>'+esc(label(k))+'</th>'+['count','mean','std','min','q1','median','q3','max'].map(p=>'<td>'+fmt(s[p],2)+'</td>').join('')+'</tr>';}).join('')}</tbody></table></div></div></details>`;
}
function renderAnalysisTable(){if(!analysisResult||!$('#analysisResult'))return;const {data,headers,title}=analysisResult;$('#analysisResult').innerHTML='<div class="spread" style="margin:18px 0 12px"><h3>'+esc(title)+'</h3>'+btn('exportAnalysis',t('导出结果 CSV','Export result CSV'),'download','small')+'</div><div class="table-scroll"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+data.slice(0,100).map(r=>'<tr>'+r.map(v=>'<td>'+esc(E.numeric(v)?fmt(v,2):val(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="card-sub">'+t('共 ','Total: ')+data.length+t(' 行，最多预览 100 行。导出包含全部结果。',' rows. Preview limited to 100 rows; export contains all results.')+'</p>';}
function historyView(){return '<div class="card"><div class="table-head spread"><div><h2>'+t('数据处理流水线','Transformation pipeline')+'</h2><p class="card-sub">'+t('每个数据集分别保留最近 20 步撤销和独立的操作记录。','Each dataset retains its own history and the last 20 undo steps.')+'</p></div>'+btn('exportHistory',t('导出操作记录','Export history'),'download','small')+'</div><div class="history-row"><span class="step-number">0</span><div class="body"><h3>'+t('载入数据','Load dataset')+'</h3><p>'+esc(dataset)+' · '+original.length+' '+t('行','rows')+'</p><code>df = pd.read_'+(dataset.endsWith('.json')?'json':/\.xlsx(?:$| \/)/i.test(dataset)?'excel':'csv')+'('+esc(JSON.stringify(dataset))+')</code></div><span class="badge">'+t('初始状态','Initial state')+'</span></div>'+history.map((h,i)=>'<div class="history-row"><span class="step-number">'+(i+1)+'</span><div class="body"><h3>'+esc(t(h.zh,h.en))+'</h3><p>'+h.before+' → '+h.after+' '+t('行','rows')+' · '+new Date(h.time).toLocaleTimeString(lang==='zh'?'zh-CN':'en-US')+'</p><code>'+esc(h.code)+'</code></div><span class="badge">'+t('已完成','Completed')+'</span></div>').join('')+(history.length?'':'<div class="empty">'+t('尚未进行数据变换。试试缺失值填充或创建计算字段。','No transformations yet. Try filling missing values or creating a calculated field.')+'</div>')+'</div><div class="insight">'+icon('help')+t('pandas 片段用于解释操作思路，并非完整可执行脚本；计算实际由本地 JavaScript 引擎完成。','The pandas snippets illustrate operations, not a complete executable script. Calculations run in a local JavaScript engine.')+'</div>';}
function modal(title,body,footer=''){const d=$('#modal');d.innerHTML='<div class="spread"><h2>'+title+'</h2>'+btn('close','','close','ghost','aria-label="'+t('关闭','Close')+'"')+'</div>'+body+(footer?'<div class="modal-footer">'+footer+'</div>':'');d.showModal();const zone=$('#dropzone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');if(e.dataTransfer.files[0])loadFile(e.dataTransfer.files[0]);});}}
function commit(next,zh,en,code,newcols){if(next.length>20000)throw Error('LIMIT');undo.push({rows:structuredClone(rows),cols:[...cols],visible:[...visible],history:structuredClone(history),prepareMode,prepareDrafts:structuredClone(prepareDrafts)});if(undo.length>20)undo.shift();history.push({zh,en,code,before:rows.length,after:next.length,time:new Date().toISOString()});pending=null;groupSpec=null;detailPage=0;detailOrder='original';rows=next;cols=newcols|| (rows.length?E.columns(rows):cols);visible=cols.filter(c=>visible.includes(c)||!undo.at(-1).cols.includes(c));analysisResult=null;render();toast(t('操作完成，可随时撤销。','Done. You can undo this operation.'));}
function error(e){const msg={EMPTY:t('文件中没有数据行。','The file has no data rows.'),CSV_QUOTE:t('CSV 引号未闭合，请检查格式。','CSV contains an unclosed quote.'),HEADERS:t('表头必须非空且不重复。','Headers must be non-empty and unique.'),CSV_WIDTH:t('CSV 数据行列数与表头不一致。','CSV row widths do not match the header.'),JSON_ROWS:t('JSON 必须为对象组成的数组。','JSON must be an array of objects.'),JSON_NESTED:t('JSON 字段必须为单个值，不能嵌套对象或数组。','JSON cells must be scalar values, not nested objects or arrays.'),LIMIT:t('文件超过 20,000 行或 80 列限制。','The file exceeds the limit of 20,000 rows or 80 columns.'),SIZE:t('文件不能超过 5 MB。','The file must be 5 MB or smaller.'),FORMAT:t('请选择 CSV、TSV、JSON 或 Excel 文件。','Choose a CSV, TSV, JSON or Excel file.'),NO_NUMERIC:t('该字段没有有效数值，无法按均值或中位数填充。','This column has no valid numbers for a mean or median.'),COLUMN_NAME:t('新字段名称不能为空或与现有字段重名。','The new column name must be non-empty and unique.'),VALUE:t('请填写有效的值。','Please enter a valid value.'),NUMERIC:t('此操作需要一个数值字段。','This operation requires a numeric field.')};toast(msg[e.message]||t('操作失败，请检查文件或输入内容。','Unable to complete. Check your file or input.'));console.warn(e.message);}
function setData(data,name,sample,replaceCurrent=false){
 if(activeDataset)datasets.save(activeDataset,captureDataset());
 studySpec={};pending=null;prepareMode='missing';prepareDrafts=null;prepareResult=null;joinData=null;joinName='';joinDatasetId='';workbook=null;rows=data;original=structuredClone(rows);cols=E.columns(rows);visible=[...cols];dataset=name;isSample=sample;history=[];undo=[];detailPage=0;detailOrder='original';analysisResult=null;
 const config=initialConfig(rows);({profileKey,groupSpec}=config);
 if(replaceCurrent)datasets.save(activeDataset,captureDataset());else activeDataset=datasets.add(captureDataset());
 render();
}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const get=id=>$('#'+id)?.value;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.act;try{
 if(navs().some(n=>n[0]===a)||a==='help'){view=a;render();window.scrollTo(0,0);}
 else if(a==='menu')$('.sidebar').classList.toggle('open');
 else if(a==='language'){lang=lang==='zh'?'en':'zh';localStorage.setItem('datalens-language',lang);analysisResult=null;render();}
 else if(a==='close')$('#modal').close();
 else if(a==='import')modal(t('导入数据','Import data'),'<p class="card-sub">'+t('导入后新增一个数据集。可在左侧切换，每个数据集分别保留处理记录和分析设置。','Import adds a dataset. Switch in the sidebar; transformations and analysis settings are retained separately.')+'</p><button type="button" id="dropzone" data-act="chooseFile" class="drop-zone" style="width:100%;display:block">'+icon('upload')+'<strong>'+t('拖拽文件到这里，或点击选择','Drop a file here, or click to browse')+'</strong><p>CSV / TSV / JSON / XLSX · UTF-8 · ≤ 5 MB</p></button><p class="card-sub">'+t('最多 20,000 行、80 列。CSV 首行为唯一表头；JSON 为对象数组。','Up to 20,000 rows and 80 columns. CSV needs unique headers; JSON must be an array of records.')+'</p>',btn('downloadSample',t('下载原始企鹅数据','Download original penguin CSV'),'download')+btn('sample',t('使用真实企鹅数据','Use penguin observations'),'spark','primary'));
 else if(a==='chooseFile')$('#fileInput').click();
 else if(a==='downloadSample')download(RAW_CSV,'penguins.csv','text/csv;charset=utf-8');
 else if(a==='sample'){const existing=datasets.list().find(d=>d.isSample);if(existing)switchDataset(existing.id);else setData(penguins(),'penguins.csv',true);$('#modal').close();}
 else if(a==='reset')modal(t('恢复原始数据？','Restore the original data?'),'<p style="margin-top:18px" class="muted">'+t('将撤回全部清洗操作，恢复到最近一次导入时的状态。','All transformations will be removed, restoring the last imported dataset.')+'</p>',btn('close',t('取消','Cancel'))+btn('confirmReset',t('恢复原始数据','Restore'),'reset','primary'));
 else if(a==='confirmReset'){setData(structuredClone(original),dataset,isSample,true);$('#modal').close();}
 else if(a==='undo'){prepareResult=null;pending=null;let s=undo.pop();if(s){prepareMode=s.prepareMode||prepareMode;prepareDrafts=s.prepareDrafts||prepareDrafts;rows=s.rows;cols=s.cols;visible=s.visible;history=s.history;detailPage=0;detailOrder='original';analysisResult=null;render();toast(t('已撤销上一步。','Last operation undone.'));}}
 else if(a==='export'){modal(t('导出当前结果','Export your results'),'<p class="card-sub" style="margin:16px 0">'+t('导出当前数据集的全部记录与可见列。','Exports all rows and visible columns from the working dataset.')+'</p><div class="status-bar">'+fmt(current().length)+' '+t('行','rows')+' × '+visible.length+' '+t('列','columns')+'</div>',btn('exportJSON','JSON','download')+btn('exportCSV','CSV','download','primary'));}
 else if(a==='exportCSV'){download(E.csv(current(),visible),'datalens_export.csv','text/csv;charset=utf-8');$('#modal').close();}
 else if(a==='exportJSON'){download(JSON.stringify(current().map(r=>Object.fromEntries(visible.map(c=>[c,r[c]]))),null,2),'datalens_export.json','application/json');$('#modal').close();}
 else if(a==='applyMissing'){let c=get('missingCol'),m=get('missingMethod'),v=get('missingValue');if(m==='custom'&&!v.trim())throw Error('VALUE');let next=m==='drop'?rows.filter(r=>!E.missing(r[c])):E.fillMissing(rows,c,m,v);commit(next,'处理缺失值：'+c,'Handle missing values: '+c,m==='drop'?'df.dropna(subset=['+JSON.stringify(c)+'])':'df['+JSON.stringify(c)+'].fillna('+(m==='custom'?JSON.stringify(E.scalar(v)):'df['+JSON.stringify(c)+'].'+m+'()')+')');}
 else if(a==='dedupe')commit(E.dedupe(rows,cols),'移除重复记录','Remove duplicate rows','df.drop_duplicates()');
 else if(a==='editColumn'){const c=get('editCol'),typ=get('editType'),name=get('renameValue').trim()||c;if(name!==c&&cols.includes(name))throw Error('COLUMN_NAME');let next=rows.map(r=>Object.fromEntries(cols.map(k=>{let v=r[k];if(k===c&&!E.missing(v)){if(typ==='number')v=Number.isFinite(Number(v))?Number(v):null;if(typ==='text')v=String(v);}return[k===c?name:k,v];})));commit(next,'调整字段：'+c,'Edit column: '+c,(typ==='number'?'pd.to_numeric(df['+JSON.stringify(c)+'], errors="coerce")':typ==='text'?'df['+JSON.stringify(c)+'].astype("string")':'')+(name!==c?'\ndf.rename(columns={'+JSON.stringify(c)+': '+JSON.stringify(name)+'})':''),cols.map(k=>k===c?name:k));}
 else if(a==='calculate'){let name=get('calcName').trim(),a=get('calcA'),b=get('calcB'),op=get('calcOp'),constant=b==='__constant'?get('calcConstant'):undefined;if(cols.length>=80)throw Error('LIMIT');if(constant!==undefined&&(constant===''||!Number.isFinite(Number(constant))))throw Error('VALUE');if(!a||!b)throw Error('NUMERIC');let next=E.compute(rows,name,a,op,b,constant);commit(next,'新增计算字段：'+name,'Calculate field: '+name,'df['+JSON.stringify(name)+'] = df['+JSON.stringify(a)+'] '+op+' '+(constant!==undefined?constant:'df['+JSON.stringify(b)+']')+(op==='/'?'  # replace division by zero with null':''));}
 else if(a==='aggregate'){let r=get('groupRow'),c=get('groupCol'),v=get('groupVal'),fn=get('groupAgg');if(fn!=='count'&&!colopts(true).some(([k])=>k===v))throw Error('NUMERIC');let data,headers;if(c){const p=E.pivot(rows,r,c,v,fn);if(p.keys.length>80)throw Error('LIMIT');headers=[label(r),...p.keys.map(k=>String(val(k)))];data=p.rows.map(r=>[r.key,...r.values]);}else{headers=[label(r),label(v)+' ('+fn+')'];data=E.groupBy(rows,r,v,fn).map(g=>[g.key,g.value]);}analysisResult={data,headers,title:label(r)+(c?' × '+label(c):'')+' / '+label(v)+' · '+fn};renderAnalysisResult();}
 else if(a==='exportAnalysis'){const {data,headers}=analysisResult;download(E.csv(data.map(r=>Object.fromEntries(r.map((v,i)=>[headers[i]+' ['+(i+1)+']',v])))),'datalens_analysis.csv','text/csv;charset=utf-8');}
 else if(a==='exportStudy'){download(E.csv(studyExport(buildStudy(rows,cols,studySpec,isSample))),'datalens_analysis.csv','text/csv;charset=utf-8');}
 else if(a==='exportStudyChart'){const source=document.getElementById(b.dataset.chart);if(!source)return;const clone=source.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('text').forEach(n=>{n.setAttribute('font-family','Microsoft YaHei, Arial, sans-serif');n.setAttribute('font-size','12');if(!n.hasAttribute('fill'))n.setAttribute('fill','#5f6b88');});clone.querySelectorAll('[data-act]').forEach(n=>{n.removeAttribute('data-act');n.removeAttribute('role');n.removeAttribute('tabindex');});download(clone.outerHTML,'datalens_'+b.dataset.chart+'.svg','image/svg+xml');}
 else if(a==='exportHistory')download(JSON.stringify({dataset,operations:history},null,2),'datalens_history.json','application/json');
 }catch(err){error(err);}});
document.addEventListener('change',e=>{if(e.target.id==='fileInput'&&e.target.files[0])loadFile(e.target.files[0]);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
// Full-dataset exploration; transformations retain explicit previews.
let prepareMode='missing',prepareDrafts=null,prepareResult=null,prepareUpdateTimer=null;
let profileKey=null,pending=null,groupSpec=null,joinData=null,joinName='',joinDatasetId='',workbook=null,importMode='replace';
function dataView(){
 const prof=E.profile(rows,cols),missing=prof.reduce((a,c)=>a+c.missing,0);
 if(!cols.includes(profileKey))profileKey=prof.find(c=>c.type==='number'&&c.missing)?.key||prof.find(c=>c.type==='number')?.key||cols[0];
 return `${sourceCard(missing)}<section class="card card-pad quality-map"><h2>${t('缺失值分布','Missing-value map')}</h2><div class="wide-viz">${extras.qualityMap(rows,cols)}</div></section>
 <section class="card profile-workspace"><div class="profile-list"><div class="profile-list-title"><h2>${t('字段画像','Field profiles')}</h2><p class="card-sub">${t('完整数据集 · 点击字段探索','Full dataset · Choose a field')}</p></div>${prof.map(c=>`<div class="profile-item ${profileKey===c.key?'active':''}"><button class="profile-pick" data-act="profile" data-key="${esc(c.key)}"><span class="field-type">${c.type==='number'?'#':c.type==='date'?'◷':'Aa'}</span><span><b>${esc(label(c.key))}</b><small>${fmt(c.unique)} ${t('个唯一值','unique values')}</small></span></button>${c.missing?`<span class="missing-badge">${fmt(c.missing)} ${t('缺失','missing')}</span>`:'<span class="complete-dot" title="'+t('无缺失','Complete')+'">✓</span>'}</div>`).join('')}</div><div class="profile-detail" id="profileDetail"></div></section>`;
}
function distribution(data,key,_unused=data,{bins=null,max=null}={}){
 bins=bins||V.binsFor([data],key);if(!bins.length)return empty(t('该字段没有有效数值。','This field has no valid numbers.'));
 const counts=V.countBins(data,key,bins),peak=max||Math.max(1,...counts.map(d=>d.value));
 const W=700,H=220,L=40,R=15,T=22,B=35,w=(W-L-R)/bins.length,y=n=>H-B-n/peak*(H-T-B);
 return `<svg class="distribution" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label(key))} ${t('频数分布','frequency distribution')}"><text x="${L}" y="13">${t('记录数','Records')}</text>${(peak>1?[0,.5,1]:[0,1]).map(f=>`<line x1="${L}" x2="${W-R}" y1="${y(peak*f)}" y2="${y(peak*f)}" stroke="#e4e7f3"/><text x="${L-7}" y="${y(peak*f)+4}" text-anchor="end">${fmt(peak*f)}</text>`).join('')}${bins.map((b,i)=>`<g><rect x="${L+i*w+3}" y="${y(counts[i].value)}" width="${Math.max(1,w-6)}" height="${H-B-y(counts[i].value)}" rx="3" fill="#4f46e5"/><title>${fmt(b.start,2)}–${fmt(b.end,2)}: ${counts[i].value}</title></g>`).join('')}<text x="${L}" y="${H-12}">${fmt(bins[0].start,2)}</text><text x="${W-R}" y="${H-12}" text-anchor="end">${fmt(bins.at(-1).end,2)}</text></svg>`;
}
function categoryPlot(key,base=rows){
 const groups=new Map();for(const r of base){const k=JSON.stringify(r[key]??null);if(!groups.has(k))groups.set(k,{value:r[key],count:0});groups.get(k).count++;}
 const all=[...groups.values()].sort((a,b)=>b.count-a.count),list=all.slice(0,8),max=Math.max(1,...list.map(g=>g.count));
 return '<div class="category-facets">'+list.map(g=>`<div class="facet-row"><span class="facet-name">${esc(val(g.value))}</span><span class="facet-track"><b style="width:${100*g.count/max}%"></b></span><span class="facet-count">${fmt(g.count)}</span></div>`).join('')+'</div>'+(all.length>8?`<p class="card-sub">${t('按完整数据频数展示前 8 类，共 ','Top 8 categories by full-dataset frequency; ')}${all.length}${t(' 类。其余记录仍保留在工作表中。',' categories total. Other records remain in the table.')} </p>`:'');
}
function boxPlot(key,data=current()){
 const s=V.outliers(data,key);if(!s.count)return fieldEmpty(null,key);
 const vals=data.map(r=>r[key]).filter(E.numeric),inside=vals.filter(v=>v>=s.lower&&v<=s.upper),lo=Math.min(...inside),hi=Math.max(...inside),x=v=>45+(v-s.min)/(s.max-s.min||1)*600;
 const out=vals.filter(v=>v<s.lower||v>s.upper);
 return `<svg viewBox="0 0 700 120" role="group" aria-label="${esc(label(key))} ${t('箱线图','box plot')}"><line x1="${x(lo)}" x2="${x(hi)}" y1="50" y2="50" stroke="#7768cf" stroke-width="2"/><path d="M${x(lo)} 36v28M${x(hi)} 36v28" stroke="#7768cf" stroke-width="2"/><rect x="${x(s.q1)}" y="29" width="${Math.max(2,x(s.q3)-x(s.q1))}" height="42" fill="#e6e1ff" stroke="#4f46e5"/><line x1="${x(s.median)}" x2="${x(s.median)}" y1="29" y2="71" stroke="#4f46e5" stroke-width="3"/>${[...new Set(out)].slice(0,300).map(v=>`<circle aria-label="${t('检查数值','Inspect value')} ${v}" cx="${x(v)}" cy="50" r="5" fill="#e7673e"><title>${v}</title></circle>`).join('')}<text x="45" y="100">${fmt(s.min,2)}</text><text x="350" y="100" text-anchor="middle">${t('中位数','Median')} ${fmt(s.median,2)}</text><text x="645" y="100" text-anchor="end">${fmt(s.max,2)}</text></svg><div class="spread"><p class="card-sub">${t('1.5 × IQR 标记疑似异常，需结合业务检查。','1.5 × IQR flags potential outliers; inspect in context.')}</p>${out.length?`<span class="badge">${fmt(out.length)} ${t('条疑似异常','potential outliers')}</span>`:''}</div>`;
}
function renderProfile(){const p=E.profile(rows,cols).find(c=>c.key===profileKey);if(!p)return;
 const stats=E.describe(rows.map(r=>r[profileKey]));
 $('#profileDetail').innerHTML=`<div class="card-head"><div><h2>${esc(label(profileKey))}</h2></div>${btn('clean',t('整理数据','Prepare data'),'chevron','small')}</div><p class="card-sub">${t('统计当前数据集的全部记录。','Statistics use the full working dataset.')}</p>${p.type==='number'?`<div class="inline-stats"><span>${t('有效值','Valid values')} <b>${fmt(stats.count)}</b></span><span>${t('均值','Mean')} <b>${fmt(stats.mean,2)}</b></span><span>${t('中位数','Median')} <b>${fmt(stats.median,2)}</b></span></div><div class="chart">${distribution(rows,profileKey)}</div><div class="chart box-chart">${boxPlot(profileKey)}</div>`:categoryPlot(profileKey)}${fieldDetailTable(p)}`;
}
function fieldDetailTable(profile){
 const d=fieldDetails(rows,profileKey,{order:detailOrder,page:detailPage}),profiles=E.profile(rows,cols);
 detailPage=d.page;
 const context=cols.find(k=>k!==profileKey&&/(^id$|_id$|编号)/i.test(k))||profiles.find(c=>c.key!==profileKey&&c.type==='text'&&c.unique<=30)?.key;
 const valueCell=v=>{if(E.missing(v))return '<span class="cell-null">'+t('缺失','Missing')+'</span>';const text=esc(isSample&&profileKey==='year'?v:E.numeric(v)?String(v):val(v));const position=d.stats.min===d.stats.max?50:(v-d.stats.min)/(d.stats.max-d.stats.min)*100;return '<span class="field-value">'+text+'</span>'+(profile.type==='number'?'<span class="field-value-track" aria-hidden="true"><i style="left:'+Math.max(0,Math.min(100,position))+'%"></i></span>':'');};
 const first=d.total?d.page*8+1:0,last=Math.min(d.total,(d.page+1)*8);
 return `<section class="field-records" data-field="${esc(profileKey)}"><div class="field-records-head"><div><h3>${t('字段明细','Field records')} · ${esc(label(profileKey))}</h3><p>${t('有效','Present')} ${fmt(d.total-d.missing)} / ${fmt(d.total)} · ${t('缺失','Missing')} ${fmt(d.missing)}</p></div>${field(t('排列','Order'),select('detailOrder',[['original',t('原始行序','Original order')],['asc',t('值从小到大','Value ascending')],['desc',t('值从大到小','Value descending')],['missingFirst',t('缺失置前','Missing first')]],detailOrder))}</div><div class="table-scroll"><table class="field-record-table"><thead><tr><th>${t('记录行号','Record row')}</th>${context?'<th>'+esc(label(context))+'</th>':''}<th>${esc(label(profileKey))}</th><th>${t('状态','Status')}</th></tr></thead><tbody>${d.records.map(r=>`<tr><td><button class="source-row-link" data-act="inspectRow" data-row="${r.index}" aria-label="${t('查看第','Inspect row ')} ${r.index+1}${t('行详情','')}">#${r.index+1}</button></td>${context?'<td>'+esc(val(r.row[context]))+'</td>':''}<td class="field-measure">${valueCell(r.value)}</td><td><span class="detail-status ${E.missing(r.value)?'missing':'present'}">${E.missing(r.value)?t('缺失','Missing'):t('完整','Present')}</span></td></tr>`).join('')}</tbody></table></div><div class="field-records-footer"><span>${first}–${last} / ${fmt(d.total)} ${t('行','rows')}</span><div class="flex">${btn('detailPrev','‹','','small',(d.page===0?'disabled ':'')+'aria-label="'+t('上一页明细','Previous records')+'"')}<span>${d.page+1} / ${d.lastPage+1}</span>${btn('detailNext','›','','small',(d.page===d.lastPage?'disabled ':'')+'aria-label="'+t('下一页明细','Next records')+'"')}</div></div>${profile.type==='number'?'<p class="field-record-note">'+t('圆点表示该值在本字段最小值—最大值中的位置；点击行号查看完整记录。','Dots locate values within this field’s min–max range. Click a row number to inspect the full record.')+'</p>':'<p class="field-record-note">'+t('切换左侧字段会同步更换明细内容；点击行号查看完整记录。','Choose a field to update these source values. Click a row number to inspect the full record.')+'</p>'}</section>`;
}
const prepareTabs=()=>[['missing','alert',t('缺失值处理','Missing values')],['duplicates','rows',t('重复数据处理','Duplicates')],['rename','columns',t('字段名称替换','Rename columns')],['calculate','plus',t('加入新字段','Add a field')]];
function cleanView(){return `<div class="prepare-tabs" role="tablist" aria-label="${t('数据处理功能','Preparation tools')}">${prepareTabs().map(([key,ic,text])=>btn('prepareMode',text,ic,'prepare-tab '+(prepareMode===key?'active':''),`role="tab" aria-selected="${prepareMode===key}" tabindex="${prepareMode===key?0:-1}" aria-controls="preparePanel" id="prepareTab-${key}" data-mode="${key}"`)).join('')}</div><section class="card prepare-panel" id="preparePanel" role="tabpanel" aria-labelledby="prepareTab-${prepareMode}"><div class="prepare-scope">${icon('shield')}<span>${t('作用范围：当前数据集全部 ','Scope: all ')}<b>${fmt(rows.length)}</b> ${t('行。参数调整只更新预览，应用后可撤销。','rows. Parameter changes update the preview; applied changes can be undone.')}</span></div><div class="prepare-workspace"><aside class="prepare-controls" id="prepareControls"></aside><div class="prepare-result"><div id="prepareStage" aria-live="off"></div><div id="prepareActionBar" class="prepare-action-bar" aria-live="polite"></div></div></div></section><details class="prepare-join" ${joinData?'open':''}><summary>${t('多表合并','Join tables')}</summary>${joinPanel()}<div id="cleanPreview" aria-live="polite"></div></details>`;}
function prepareControls(){const d=prepareDrafts[prepareMode],nums=colopts(true);
 if(prepareMode==='missing'){const numeric=nums.some(o=>o[0]===d.column);return field(t('处理字段','Column'),select('missingCol',colopts(),d.column))+field(t('处理方式','Method'),select('missingMethod',[...(numeric?[['mean',t('均值填充','Fill mean')],['median',t('中位数填充','Fill median')]]:[]),['custom',t('自定义填充','Custom fill')],['drop',t('删除缺失行','Drop missing rows')]],d.method))+field(t('填充值','Fill value'),`<input id="missingValue" value="${esc(d.value)}" ${d.method==='custom'?'':'disabled'} placeholder="${t('仅自定义填充时填写','For custom fill only')}">`)+`<p class="prepare-control-note">${t('缺失包括空单元格；处理仅作用于所选字段。删除缺失行会移除整条记录。','Empty cells count as missing. Filling affects the chosen field; dropping removes the entire row.')}</p><span class="code-tag">fillna / dropna</span>`;}
 if(prepareMode==='duplicates'){const count=rows.length-E.dedupe(rows,cols).length;return `<div class="prepare-dedupe-count"><b>${fmt(count)}</b><span>${t('条重复记录','duplicate rows')}</span></div><p class="prepare-control-note">${t('比较全部 ','Compare all ')}${cols.length}${t(' 个字段，内容完全相同的记录仅保留第一次出现的一条。',' fields; keep the first row for each exact duplicate.')}</p><span class="code-tag">drop_duplicates</span>`;}
 if(prepareMode==='rename')return field(t('原字段','Column'),select('editCol',colopts(),d.column))+field(t('新字段名称','New name'),`<input id="renameValue" value="${esc(d.name)}" placeholder="${t('输入新名称','Enter a new name')}">`)+field(t('字段类型（可选）','Type (optional)'),select('editType',[['keep',t('保持原类型','Keep type')],['number',t('转换为数值','Convert to number')],['text',t('转换为文本','Convert to text')]],d.type))+`<p class="prepare-control-note">${t('新名称必须唯一。更名保留字段顺序与数值；转换失败的数值将成为缺失值。','Names must be unique. Renaming preserves column order and values; failed numeric conversions become null.')}</p><span class="code-tag">rename / astype</span>`;
 return field(t('左侧字段','Left field'),select('calcA',nums,d.a))+`<div class="prepare-small-row">${field(t('运算','Operator'),select('calcOp',[['+','+'],['-','−'],['*','×'],['/','÷']],d.op))}${field(t('右侧字段','Right field'),select('calcB',[...nums,['__constant',t('使用常数','Constant')]],d.b))}</div>`+field(t('常数','Constant'),`<input id="calcConstant" type="number" value="${esc(d.constant)}" ${d.b==='__constant'?'':'disabled'}>`)+field(t('新字段名称','New field name'),`<input id="calcName" value="${esc(d.name)}" placeholder="new_measure">`)+`<p class="prepare-control-note">${t('逐行计算；缺失输入、除零和非有限结果返回空值。','Calculated per row. Missing inputs, division by zero and non-finite results return null.')}</p><span class="code-tag">assign</span>`;
}
function readPrepareDraft(){const d=prepareDrafts[prepareMode];if(prepareMode==='missing')Object.assign(d,{column:get('missingCol'),method:get('missingMethod'),value:get('missingValue')});if(prepareMode==='rename')Object.assign(d,{column:get('editCol'),name:get('renameValue'),type:get('editType')});if(prepareMode==='calculate')Object.assign(d,{a:get('calcA'),op:get('calcOp'),b:get('calcB'),constant:get('calcConstant'),name:get('calcName')});}
function renderPrepare(controls=true){if(!$('#prepareStage'))return;clearTimeout(prepareUpdateTimer);prepareDrafts=P.reconcilePrepareDrafts(rows,cols,prepareDrafts);if(controls)$('#prepareControls').innerHTML=prepareControls();
 const joinPending=pending&&pending.kind!=='prepare'?pending:null;let result,problem='',applied=prepareResult?.mode===prepareMode;
 try{result=applied?prepareResult:P.previewPrepare(rows,cols,prepareMode,prepareDrafts[prepareMode]);}catch(e){problem=e.message;}
 if(joinPending)pending=joinPending;else pending=null;
 const titles={missing:t('缺失数量与分布','Missing values & distribution'),duplicates:t('重复记录去向','Duplicate disposition'),rename:t('字段映射','Column mapping'),calculate:t('计算结果','Calculated results')};
 if(problem){const messages={COLUMN_NAME:t('请填写一个不与已有字段重名的新名称。','Enter a new, unique column name.'),VALUE:t('请补全参数以生成预览。','Complete the parameters to preview.'),NUMERIC:t('此计算需要数值字段，请先检查字段类型。','This calculation requires numeric fields.'),NO_NUMERIC:t('该字段没有数值，改用自定义填充或删除缺失行。','No numeric values. Use custom fill or drop missing rows.'),LIMIT:t('最多支持 80 个字段。','A maximum of 80 fields is supported.')};$('#prepareStage').dataset.state='error';$('#prepareStage').innerHTML=`<div class="prepare-stage-head"><h2>${titles[prepareMode]}</h2><span class="badge">${t('待完善参数','Parameters needed')}</span></div><div class="prepare-validation">${icon('help')}<p>${messages[problem]||t('请检查字段和输入参数。','Check the fields and parameters.')}</p></div>`;$('#prepareActionBar').innerHTML=btn('applyPrepared',t('应用处理','Apply changes'),'check','primary','disabled');return;}
 if(!applied&&!result.noChange&&!joinPending){const title=prepareTabs().find(x=>x[0]===prepareMode)[2];pending={kind:'prepare',next:result.after,newcols:result.afterCols,key:result.key,afterKey:result.afterKey,zh:lang==='zh'?title:prepareTabsChinese[prepareMode],en:prepareTabsEnglish[prepareMode],code:result.code,result};}
 $('#prepareStage').dataset.state=applied?'applied':'preview';$('#prepareStage').innerHTML=`<div class="prepare-stage-head"><h2>${titles[prepareMode]}</h2><span class="badge ${applied?'applied-badge':''}">${applied?t('已应用','Applied'):t('预览 · 未应用','Preview · Not applied')}</span></div>${prepareVisuals.render(result)}`;
 const summary=joinPending?t('请先应用或取消下方的合并预览。','Apply or cancel the join preview below first.'):applied?t('已应用到当前数据集，可以使用顶部撤销。','Applied to this dataset. Use Undo above to revert.'):result.noChange?t('当前设置不会改变数据。','These settings do not change the data.'):t('预览已更新，确认后再应用。','Preview updated. Apply when ready.');
 $('#prepareActionBar').innerHTML=`<span>${summary}</span><div class="flex">${btn('resetPrepareDraft',t('恢复本项设置','Reset parameters'),'reset','small ghost')}${btn('applyPrepared',applied?t('已应用','Applied'):t('应用处理','Apply changes'),'check','primary',applied||result.noChange||joinPending?'disabled':'')}</div>`;
}
const prepareTabsChinese={missing:'缺失值处理',duplicates:'重复数据处理',rename:'字段名称替换',calculate:'加入新字段'},prepareTabsEnglish={missing:'Handle missing values',duplicates:'Remove duplicates',rename:'Rename columns',calculate:'Add a calculated field'};
function updatePrepareInput(e){if(view!=='clean'||!e.target.closest('#prepareControls'))return;readPrepareDraft();prepareResult=null;pending=null;$('#cleanPreview').innerHTML='';clearTimeout(prepareUpdateTimer);const id=activeDataset,mode=prepareMode;
 if(e.type==='change'){renderPrepare(['missingCol','missingMethod','editCol','calcB'].includes(e.target.id));return;}
 $('#prepareActionBar').innerHTML=`<span>${t('正在更新预览…','Updating preview…')}</span>${btn('applyPrepared',t('应用处理','Apply changes'),'check','primary','disabled')}`;prepareUpdateTimer=setTimeout(()=>{if(view==='clean'&&activeDataset===id&&prepareMode===mode)renderPrepare(false);},150);
}
document.addEventListener('input',updatePrepareInput);document.addEventListener('change',updatePrepareInput);
document.addEventListener('keydown',e=>{const tab=e.target.closest('.prepare-tab');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const modes=prepareTabs().map(x=>x[0]),i=modes.indexOf(prepareMode),next=e.key==='Home'?0:e.key==='End'?modes.length-1:(i+(e.key==='ArrowRight'?1:-1)+modes.length)%modes.length;clearTimeout(prepareUpdateTimer);prepareMode=modes[next];pending=null;render();$('#prepareTab-'+prepareMode).focus();});


function joinPanel(){return `<section class="card card-pad join-panel"><div class="spread"><div><h2>${t('合并另一张表','Join another table')}</h2><p class="card-sub">${t('按键匹配，预览匹配率和新增行；空键不匹配，数字与文本键区分类型。','Match keys and preview coverage and expanded rows. Null keys do not match; numeric and text keys are distinct.')}</p></div>${btn('joinFile',t('选择文件','Choose file'),'upload','small')}</div>${datasetJoinPicker()}${joinData?`<p class="card-sub">${esc(joinName)} · ${joinData.length} ${t('行','rows')}</p><div class="form-row">${field(t('当前表关联键','Current table key'),select('joinLeft',colopts()))}${field(t('另一表关联键','Other table key'),select('joinRight',E.columns(joinData).map(k=>[k,k])))}${field(t('合并方式','Join type'),select('joinHow',[['left',t('左连接 · 保留当前表所有行','Left · Keep all current rows')],['inner',t('内连接 · 仅匹配行','Inner · Matching rows only')]]))}${btn('previewJoin',t('预览合并','Preview join'),'analysis','primary')}</div>`:`<p class="card-sub join-hint">CSV / TSV / JSON / XLSX · ${t('支持一对多匹配；结果最多 20,000 行。','One-to-many matches supported; at most 20,000 result rows.')}</p>`}</section>`;}
function prepareAction(a){if(a!=='previewJoin'||!joinData)return;const j=V.join(rows,joinData,get('joinLeft'),get('joinRight'),get('joinHow')),key=colopts(true)[0]?.[0]||cols[0];pending={kind:'join',next:j.rows,key,afterKey:key,newcols:j.cols,zh:'合并表格：'+joinName,en:'Join table: '+joinName,code:`df.merge(other, left_on=${JSON.stringify(get('joinLeft'))}, right_on=${JSON.stringify(get('joinRight'))}, how=${JSON.stringify(get('joinHow'))})`,join:j};showPreview();renderPrepare(false);$('#cleanPreview').scrollIntoView({behavior:'smooth',block:'start'});}
function showPreview(){if(!pending||!$('#cleanPreview'))return;const {next,key,afterKey,join}=pending;
 const before=rows.map(r=>({value:r[key]})),after=next.map(r=>({value:r[afterKey]})),bins=V.binsFor([before,after],'value'),b=E.describe(before.map(r=>r.value)),a=E.describe(after.map(r=>r.value));
 const max=Math.max(1,...V.countBins(before,'value',bins).map(d=>d.value),...V.countBins(after,'value',bins).map(d=>d.value));
 const mini=(title,data,stats)=>`<div><h3>${title}</h3><div class="inline-stats"><span>${t('行数','Rows')} <b>${data.length}</b></span><span>${t('缺失','Missing')} <b>${data.filter(r=>E.missing(r.value)).length}</b></span><span>${t('均值','Mean')} <b>${fmt(stats.mean,2)}</b></span></div><div class="chart">${bins.length?distribution(data,'value',data,{interactive:false,bins,max}):empty(t('非数值字段：请查看下方记录预览。','Non-numeric field: inspect the record preview below.'))}</div></div>`;
 const changes=[];if(!join&&next.length===rows.length)for(let i=0;i<next.length&&changes.length<8;i++){if(JSON.stringify(rows[i])!==JSON.stringify(next[i]))changes.push([i+1,rows[i][key],next[i][afterKey]]);}
 $('#cleanPreview').innerHTML=`<section class="card card-pad preview-panel"><div class="spread"><div><h2>${esc(t(pending.zh,pending.en))}</h2></div>${btn('cancelPreview',t('取消预览','Cancel preview'),'close','small')}</div>${join?`<div class="inline-stats"><span>${t('匹配原表行','Matched source rows')} <b>${join.matched}</b></span><span>${t('未匹配','Unmatched')} <b>${join.unmatched}</b></span><span>${t('一对多新增行','Extra rows from multiple matches')} <b>${join.extra}</b></span></div>`:''}<p class="card-sub">${t('比较字段','Comparison field')}: ${esc(label(key))} · ${t('左右使用相同坐标范围、分箱和频数上限。','Both sides share bin boundaries and axis scales.')}</p><div class="preview-quality wide-viz">${extras.qualityChange(rows,next,cols,pending.newcols||cols)}</div><div class="comparison-grid">${mini(t('处理前','Before'),before,b)}${mini(t('处理后','After'),after,a)}</div>${changes.length?`<div class="table-scroll"><table><thead><tr><th>${t('原行号','Source row')}</th><th>${t('原值','Before')}</th><th>${t('新值','After')}</th></tr></thead><tbody>${changes.map(r=>'<tr>'+r.map(v=>'<td>'+esc(E.numeric(v)?fmt(v,3):val(v))+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:`<p class="card-sub">${t('结果行数','Result rows')}: ${rows.length} → ${next.length}</p>`}${join?`<div class="table-scroll"><table><thead><tr>${(pending.newcols||cols).map(k=>'<th>'+esc(label(k))+'</th>').join('')}</tr></thead><tbody>${next.slice(0,5).map(r=>'<tr>'+(pending.newcols||cols).map(k=>'<td>'+esc(val(r[k]))+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:''}<div class="preview-footer"><p class="card-sub">${t('确认效果后应用；完成后可以撤销。','Apply after reviewing. You can undo the operation.')}</p>${btn('confirmPreview',t('应用这次处理','Apply transformation'),'check','primary')}</div></section>`;
}
function renderAnalysisResult(){
 if(!$('#analysisResult'))return;
 if(!groupSpec||!cols.includes(groupSpec.r)||!cols.includes(groupSpec.v)||(groupSpec.c&&!cols.includes(groupSpec.c)))groupSpec=initialConfig(rows).groupSpec;
 const {r,c,v,fn}=groupSpec;let data,headers;
 if(!r||!v)return;
 if(c){const p=E.pivot(rows,r,c,v,fn);headers=[label(r),...p.keys.map(k=>String(val(k)))];data=p.rows.map(r=>[r.key,...r.values]);}
 else{headers=[label(r),label(v)+' ('+fn+')',t('记录数','Rows')];data=E.groupBy(rows,r,v,fn).map(g=>[g.key,g.value,g.count]);}
 analysisResult={data,headers,title:label(r)+' / '+label(v)};renderAnalysisTable();
}

function helpView(){return `<section class="card card-pad"><h2>${t('使用指南','Guide')}</h2><div class="guide-steps">${[[t('数据','Data'),t('添加真实数据集，查看缺失与字段明细。','Add datasets and inspect missing values and field records.')],[t('处理','Prepare'),t('预览填补、去重、更名或计算字段，再应用与撤销。','Preview filling, deduplication, renaming or calculated fields; apply and undo.')],[t('分析','Analyze'),t('围绕指标比较群体差异、检验变量关系，再做分层核对。调整字段将同步更新图形与结论。','Compare groups, examine associations and check within strata. Changing fields updates the charts and findings together.')]].map(([h,p],i)=>'<article><h3>'+h+'</h3><p>'+p+'</p></article>').join('')}</div><p class="study-note">${t('默认使用 Palmer Penguins 的 344 条真实观测（CC0）。支持 CSV、TSV、JSON、Excel；单文件最多 5 MB、20,000 行、80 列。每个数据集分别保留处理和分析设置；数据只在当前页面会话保存，刷新前请导出。','The default contains 344 real Palmer Penguins observations (CC0). Import CSV, TSV, JSON or Excel, up to 5 MB, 20,000 rows and 80 columns per file. Datasets retain independent processing and analysis settings for this page session; export before refreshing.')}</p><p class="study-note">${t('分析使用完整工作数据，图形不会筛除记录。统计忽略缺失数值，标准差为样本标准差；相关系数使用全部有效配对，常量字段返回空值。箱线和散点抽样只影响显示，图旁注明数量。分层比较不自动判断显著性，相关不代表因果。','Analysis uses all working records; charts do not filter rows. Statistics omit missing numeric values and use sample standard deviation. Correlations use all valid pairs and are undefined for constant fields. Point sampling only affects display, with counts stated alongside charts. Stratification does not establish significance; correlation is not causation.')}</p><p class="study-note">${t('统计明细与透视表可展开使用，图形可导出 SVG，分析明细可导出 CSV。参考 pandas 的能力，以本地 JavaScript 实现。','Expand statistics and pivot tables for detailed calculations. Export charts as SVG and analysis data as CSV. pandas-inspired operations run in local JavaScript.')}</p></section>`;}
async function loadFile(file){try{if(file.size>5*1024*1024)throw Error('SIZE');const ext=file.name.toLowerCase().split('.').pop();if(['xlsx','xls'].includes(ext)){if(!window.XLSX)throw Error('FORMAT');workbook={book:XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),name:file.name,mode:importMode};modal(t('选择 Excel 工作表','Choose an Excel sheet'),'<div class="form-row">'+field(t('工作表','Worksheet'),select('excelSheet',workbook.book.SheetNames.map(n=>[n,n])))+'</div>',btn('readSheet',t('载入工作表','Load sheet'),'check','primary'));return;}if(!['csv','tsv','json'].includes(ext))throw Error('FORMAT');const txt=await file.text(),data=ext==='json'?E.validate(JSON.parse(txt)):E.parseCSV(txt,ext==='tsv'?'\t':',');acceptData(data,file.name,importMode);}catch(e){error(e);}$('#fileInput').value='';}
function acceptData(data,name,mode){if(mode==='join'){joinData=data;joinName=name;joinDatasetId='';pending=null;view='clean';render();}else setData(data,name,false);$('#modal').close();$('#fileInput').value='';importMode='replace';toast(t('已载入 ','Loaded ')+data.length+t(' 行。',' rows.'));}
document.addEventListener('click',e=>{const button=e.target.closest('[data-act]');if(!button||button.disabled)return;const a=button.dataset.act;
 const own=['applyPrepared','prepareMode','resetPrepareDraft','detailPrev','detailNext','inspectRecords','source','profile','applyMissing','dedupe','editColumn','calculate','previewJoin','confirmPreview','cancelPreview','history','aggregate','inspectRow','joinFile','readSheet'];
 if(a==='import'){importMode='replace';return;}if(['undo','confirmReset','sample'].includes(a)){pending=null;groupSpec=null;}if(a==='data')$('#modal').close();
 if(!own.includes(a))return;e.preventDefault();e.stopImmediatePropagation();try{
 if(a==='prepareMode'){clearTimeout(prepareUpdateTimer);prepareMode=button.dataset.mode;pending=null;render();}
 else if(a==='resetPrepareDraft'){clearTimeout(prepareUpdateTimer);prepareDrafts=P.reconcilePrepareDrafts(rows,cols,prepareDrafts);prepareDrafts[prepareMode]=P.defaultPrepareDrafts(rows,cols)[prepareMode];prepareResult=null;pending=null;renderPrepare();}
 else if(a==='source'){modal(t('数据来源与字段说明','Source & field guide'),sourceDetails());}
 else if(a==='inspectRecords'){const list=current();modal(t('数据记录','Dataset records'),`<p class="card-sub">${t('共','Total')} ${fmt(list.length)} ${t('条，预览前 8 条；字段明细位于“数据”。','rows. Preview of the first 8; field details are in Data.')}</p><div class="record-grid">${list.slice(0,8).map(r=>`<button class="record-chip" data-act="inspectRow" data-row="${rows.indexOf(r)}">#${rows.indexOf(r)+1}<span>${esc(val(r[cols[0]]))}</span>${icon('chevron')}</button>`).join('')||empty(t('没有匹配记录','No matching records'))}</div>`,btn('data',t('转到字段明细','Open field details'),'table','primary'));}
 else if(a==='profile'){profileKey=button.dataset.key;detailPage=0;detailOrder='original';render();}
 else if(a==='detailPrev'||a==='detailNext'){detailPage+=a==='detailPrev'?-1:1;renderProfile();}
 else if(a==='previewJoin')prepareAction(a);
 else if(a==='applyPrepared'&&pending?.kind==='prepare'){const p=pending;prepareResult=p.result;commit(p.next,p.zh,p.en,p.code,p.newcols);}
 else if(a==='confirmPreview'&&pending?.kind==='join'){const p=pending;prepareResult=p.kind==='prepare'?p.result:null;commit(p.next,p.zh,p.en,p.code,p.newcols);}
 else if(a==='cancelPreview'){pending=null;$('#cleanPreview').innerHTML='';renderPrepare(false);}
 else if(a==='history')modal(t('操作记录','Activity history'),historyView());
 else if(a==='aggregate'){const fn=get('groupAgg'),v=get('groupVal');if(fn!=='count'&&!colopts(true).some(([k])=>k===v))throw Error('NUMERIC');groupSpec={r:get('groupRow'),c:get('groupCol'),v,fn};renderAnalysisResult();}
 else if(a==='inspectRow'){const r=rows[Number(button.dataset.row)];if(r)modal(t('原始记录详情','Source record details'),'<div class="table-scroll"><table><tbody>'+cols.map(k=>'<tr><th>'+esc(label(k))+'</th><td>'+esc(val(r[k]))+'</td></tr>').join('')+'</tbody></table></div>');}
 else if(a==='joinFile'){importMode='join';$('#fileInput').click();}
 else if(a==='readSheet'){const w=workbook,table=XLSX.utils.sheet_to_json(w.book.Sheets[get('excelSheet')],{header:1,defval:null,raw:true});if(table.length<2)throw Error('EMPTY');const headers=table.shift().map(x=>String(x??'').trim());if(headers.some(x=>!x)||new Set(headers).size!==headers.length)throw Error('HEADERS');const data=E.validate(table.filter(r=>r.some(x=>!E.missing(x))).map(r=>Object.fromEntries(headers.map((k,i)=>[k,r[i] instanceof Date?r[i].toISOString().slice(0,10):r[i]??null]))));acceptData(data,w.name+' / '+get('excelSheet'),w.mode);}
 }catch(err){error(err);}
},true);
document.addEventListener('change',e=>{if(e.target.id.startsWith('study-')){const id=e.target.id;studySpec={...studySpec,[id.slice(6)]:e.target.value};render();$('#'+id)?.focus();return;}if(e.target.id==='detailOrder'){detailOrder=e.target.value;detailPage=0;renderProfile();return;}if(e.target.id==='datasetSelect'){switchDataset(e.target.value);return;}if(e.target.id==='joinDataset'){const id=e.target.value;joinDatasetId=id;if(id){const other=datasets.get(id);joinData=other.rows;joinName=other.dataset;}else{joinData=null;joinName='';}pending=null;render();return;}if(view==='clean'&&e.target.closest('.tool-card,.join-panel')){pending=null;$('#cleanPreview').innerHTML='';}});
document.addEventListener('input',e=>{if(view==='clean'&&e.target.closest('.tool-card,.join-panel')){pending=null;$('#cleanPreview').innerHTML='';}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-act]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
function sourceCard(missing){return '<div class="dataset-stats"><span><b>'+fmt(rows.length)+'</b> '+t('行','rows')+'</span><span><b>'+cols.length+'</b> '+t('列','columns')+'</span><span><b>'+missing+'</b> '+t('个缺失单元格','missing cells')+'</span><span><b>'+fmt(rows.length-E.dedupe(rows,cols).length)+'</b> '+t('条重复记录','duplicate rows')+'</span>'+btn('source',t('数据来源与字段','Source & fields'),'book','small ghost')+'</div>';}
function sourceDetails(){if(!isSample)return importedDetails();return `<p class="source-description">${t('数据由 Kristen Gorman 博士及 Palmer Station Antarctica LTER 采集，Palmer Penguins 项目整理发布。这里使用原始项目提供的简化版 penguins.csv，包含 2007—2009 年的 344 条真实观测。','Collected by Dr. Kristen Gorman and Palmer Station Antarctica LTER, and distributed by the Palmer Penguins project. This site uses their simplified penguins.csv: 344 real observations from 2007–2009.')}</p><div class="reference-links"><a href="https://allisonhorst.github.io/palmerpenguins/" target="_blank" rel="noreferrer">${t('项目与数据来源','Project & provenance')} ↗</a><a href="https://allisonhorst.github.io/palmerpenguins/reference/penguins.html" target="_blank" rel="noreferrer">${t('官方字段说明','Official field guide')} ↗</a><a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">CC0 ↗</a><a href="./data/penguins.csv" download>${t('下载原始 CSV','Download original CSV')} ↓</a></div><p class="source-description">${t('原始文件完整保留。仅将其 NA 标记识别为缺失值；没有补造记录或测量值。物种名和字段名仅在显示时翻译，导出保留原始标识。','The original file is preserved. Only NA markers are interpreted as null; no records or measurements are generated. Display labels are translated; exports retain original identifiers.')}</p><div class="table-scroll"><table><tbody>${['species','island','bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','sex','year'].map(k=>`<tr><th>${k}</th><td>${t(...names[k])}</td></tr>`).join('')}</tbody></table></div><p class="card-sub">${t('获取日期：2026-10-15。校验信息见','Retrieved 2026-10-15. Checksum and provenance:')} <a href="./data/source.json" target="_blank">source.json ↗</a></p>`;}
function datasetSize(){return '<span class="dataset-size">'+icon('rows')+fmt(rows.length)+' '+t('行','rows')+'</span>';}
function fieldEmpty(state,key){const isEmpty=!rows.length;return `<div class="selection-empty"><strong>${isEmpty?t('当前工作数据没有记录','The working dataset has no rows'):t('该字段没有有效数值','This field has no valid numbers')}</strong><p>${isEmpty?t('请恢复原始数据，或添加另一个数据集。','Restore the original data or add another dataset.'):t('请选择其他数值字段，或在“处理”中检查缺失值与字段类型。','Choose another numeric field or inspect missing values and field types in Prepare.')}</p>${isEmpty?btn('reset',t('恢复原始数据','Restore original'),'reset','small'):''}</div>`;}

function categoryFields(){return E.profile(rows,cols).filter(c=>c.type!=='date'&&c.unique<=30).sort((a,b)=>Number(a.type==='number')-Number(b.type==='number')).map(c=>[c.key,label(c.key)]);}
function captureDataset(){return {studySpec,rows,original,cols,dataset,isSample,history,undo,detailPage,detailOrder,visible,analysisResult,profileKey,groupSpec,joinData,joinName,joinDatasetId,prepareMode,prepareDrafts,prepareResult};}
function switchDataset(id){if(id===activeDataset)return;datasets.save(activeDataset,captureDataset());const state=datasets.get(id);({studySpec,rows,original,cols,dataset,isSample,history,undo,detailPage,detailOrder,visible,analysisResult,profileKey,groupSpec,joinData,joinName,joinDatasetId,prepareMode,prepareDrafts,prepareResult}=state);activeDataset=id;pending=null;workbook=null;$('#modal').close();render();}
function datasetPicker(){return `<div class="dataset-picker"><label for="datasetSelect">${t('数据集','Dataset')} <span>${datasets.list().length}</span></label><select id="datasetSelect" title="${esc(dataset)}">${datasets.list().map(d=>opt(d.id,d.name+' · '+(d.id===activeDataset?rows.length:d.rows)+' '+t('行','rows'),d.id===activeDataset?d.id:null)).join('')}</select><small>${t('当前页面会话 · 切换保留处理结果','This page session · Switching preserves changes')}</small></div>`;}
function datasetJoinPicker(){const other=datasets.list().filter(d=>d.id!==activeDataset);return other.length?'<div class="form-row">'+field(t('使用已载入的数据集','Use a loaded dataset'),select('joinDataset',[['',t('选择数据集','Choose dataset')],...other.map(d=>[d.id,d.name+' · '+d.rows+' '+t('行','rows')])],joinDatasetId))+'</div>':'';}
function importedDetails(){return `<p class="source-description">${t('来源：本地导入文件','Source: locally imported file')} <strong>${esc(dataset)}</strong>。${t('原始导入','Original import')}: ${original.length} ${t('行','rows')} × ${E.columns(original).length} ${t('列','columns')}。</p><div class="table-scroll"><table><thead><tr><th>${t('字段','Field')}</th><th>${t('类型','Type')}</th><th>${t('缺失','Missing')}</th></tr></thead><tbody>${E.profile(rows,cols).map(c=>`<tr><th>${esc(c.key)}</th><td>${c.type==='number'?t('数值','Number'):c.type==='date'?t('日期','Date'):t('文本','Text')}</td><td>${c.missing}</td></tr>`).join('')}</tbody></table></div>`;}

const extras=createVisuals({t,esc,label,val,fmt,short,shortLabel,color,getRows:()=>rows});
const studyView=createStudyView({t,esc,label,val,fmt,color,field,select,btn});
const prepareVisuals=createPrepareVisuals({t,esc,label,val,fmt,short,extras});
const initial=initialConfig(rows);({profileKey,groupSpec}=initial);
activeDataset=datasets.add(captureDataset());
render();
